public final class NativeEconomySmokeTest {
    private static int checks;
    private static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
    private static void same(Object a,Object b,String text){check(Objects.equals(a,b),text+": "+a+" != "+b);}
    private static void rejects(Runnable action,String text){try{action.run();throw new AssertionError(text);}catch(IllegalArgumentException|IllegalStateException expected){check(true,text);}}
    private static NativeCampaignV5 campaign(){return NativeProgressionScreen.freshCampaign();}
    private static ShopInventory shop(int id){var s=new ShopInventory(id,"Stock test");s.addEntry(new ShopEntry(101,2,1));s.addEntry(new ShopEntry(101,2,1));s.addEntry(new ShopEntry(111,-1,1,null,true));s.addEntry(new ShopEntry(101));s.addEntry(new ShopEntry(101,0,1));s.addEntry(new ShopEntry(101,1,1,QuestFlag.MISC_FLAG_60,false));return s;}
    public static void main(String[] args)throws Exception{
        if(args.length>0){var content=DiagnosticContent.load(Path.of(args[1]));var app=new DiagnosticApplication(content,()->{});app.loadNative(Path.of(args[2]));var c=app.nativeCampaign();var s=content.shops().get(DiagnosticContent.SHOP);same(0,c.shopState().quote(NativeShopState.registered(s),s,2,c::hasFlag).remaining(),"child exhausted stock");check(!c.shopState().quote(NativeShopState.registered(s),s,3,c::hasFlag).visible(),"child one-time listing hidden");same(2,c.party().get(0).level(),"child trained level");same(List.of(Action.THRUST),c.party().get(0).readied(),"child readied move");System.out.println("NATIVE_ECONOMY_CHILD PASS");return;}
        guild();stock();Path root=Files.createTempDirectory("native-economy-");try{screen(root);System.out.println("NATIVE_ECONOMY checks="+checks+" PASS");}finally{try(var files=Files.walk(root)){for(var p:files.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
    }
    private static void guild(){
        var c=campaign();var m=c.party().get(0);m.runtime().awardExperience(100);var terms=new GuildData(5,2,2);same(7L,c.trainingCost(m,terms),"counter cost base plus current level scale");check(c.canTrain(m,terms),"qualified counter training");var result=c.train(m,terms);same(7,result.cost(),"actual counter debit");same(33L,c.gold(),"counter overrides curriculum price");same(2,m.level(),"one level per training");same(Set.of(Action.THRUST),m.learned(),"curriculum still chooses learned move");same(9L,c.trainingCost(m,terms),"price recomputes at new current level");check(!c.canTrain(m,terms),"target level beyond guild cap blocked");rejects(()->c.train(m,terms),"cap rejects transaction");same(33L,c.gold(),"cap failure no debit");same(Set.of(Action.THRUST),m.learned(),"cap failure cannot learn next move");
        c.train(m,new GuildData(5,2,0));same(3,m.level(),"zero cap permits defined curriculum level");check(m.learned().contains(Action.SLASH),"defined next curriculum technique taught");same(24L,c.gold(),"second authored cost exact");
        var poor=campaign();var p=poor.party().get(0);p.runtime().awardExperience(100);rejects(()->poor.train(p,new GuildData(100,0,0)),"unaffordable guild rejected");same(1,p.level(),"no partial level on poor training");check(p.learned().isEmpty(),"no partial unlock on poor training");same(40L,poor.gold(),"no partial gold on poor training");
        check(poor.trainingCost(p,new GuildData(Integer.MAX_VALUE,Integer.MAX_VALUE,0))>Integer.MAX_VALUE,"guild quote uses long");rejects(()->poor.train(p,new GuildData(Integer.MAX_VALUE,Integer.MAX_VALUE,0)),"large price cannot wrap");rejects(()->poor.train(p,new GuildData(-1,0,0)),"negative authored cost rejected");rejects(()->poor.canTrain(p,new GuildData(0,0,-1)),"negative cap rejected");same(1,p.level(),"invalid terms preserve level");var free=poor.train(p,new GuildData(0,0,2));same(0,free.cost(),"authored free training supported");same(40L,poor.gold(),"free training no purse debit");
    }
    private static void stock(){
        var c=campaign();c.addGold(1000);var m=c.party().get(0);var s=shop(3);String key=NativeShopState.registered(s);
        same(2,c.shopState().quote(key,s,0,c::hasFlag).remaining(),"initial finite stock");same(10,c.buy(key,s,0,m).price(),"purchase price quote");same(1,c.shopState().quote(key,s,0,c::hasFlag).remaining(),"finite stock decremented");same(2,c.shopState().quote(key,s,1,c::hasFlag).remaining(),"identical duplicate listing independent by row");c.buy(key,s,0,m);same(0,c.shopState().quote(key,s,0,c::hasFlag).remaining(),"finite listing exhausted");long gold=c.gold();rejects(()->c.buy(key,s,0,m),"exhausted purchase refused");same(gold,c.gold(),"exhausted purchase no debit");same(101,m.getInventoryItemId(0),"purchase reaches owned native record");
        c.buy(key,s,2,m);check(!c.shopState().quote(key,s,2,c::hasFlag).visible(),"one-time unlimited listing hidden after purchase");rejects(()->c.buy(key,s,2,m),"one-time cannot repeat");c.buy(key,s,3,m);c.buy(key,s,3,m);same(-1,c.shopState().quote(key,s,3,c::hasFlag).remaining(),"unlimited remains unlimited");same(2,c.shopState().snapshot().size(),"ordinary unlimited purchases need no ledger record");
        rejects(()->c.buy(key,s,4,m),"zero initial quantity is sold out");check(!c.shopState().quote(key,s,5,c::hasFlag).visible(),"required flag gates listing");rejects(()->c.buy(key,s,5,m),"hidden listing cannot be purchased directly");c.setFlag(QuestFlag.MISC_FLAG_60);c.buy(key,s,5,m);same(0,c.shopState().quote(key,s,5,c::hasFlag).remaining(),"flag unlocked finite listing consumed");
        var other=shop(4);same(2,c.shopState().quote(NativeShopState.registered(other),other,0,c::hasFlag).remaining(),"separate catalog independent");rejects(()->c.buy(key,other,0,m),"registered key cannot alias another shop");same(2,c.shopState().quote(NativeShopState.inline(7,2,3),s,0,c::hasFlag).remaining(),"inline catalog distinct from registry");c.buy(NativeShopState.inline(7,2,3),s,0,m);same(2,c.shopState().quote(NativeShopState.inline(7,3,3),s,0,c::hasFlag).remaining(),"separate inline counter independent");
        var poor=campaign();var pricey=new ShopInventory(9,"Poor");pricey.addEntry(new ShopEntry(100,1,1));rejects(()->poor.buy(NativeShopState.registered(pricey),pricey,0,poor.party().get(0)),"poor purchase refused");check(poor.shopState().snapshot().isEmpty(),"poor purchase does not decrement stock");same(40L,poor.gold(),"poor purse unchanged");
        var full=campaign();var fm=full.party().get(0);for(int i=0;i<fm.inventorySlots();i++)fm.setInventoryItem(i,101);rejects(()->full.buy(key,s,0,fm),"full pack purchase refused");check(full.shopState().snapshot().isEmpty(),"full pack preserves stock");same(40L,full.gold(),"full pack no debit");
        var huge=new ShopInventory(10,"Huge");huge.addEntry(new ShopEntry(101,1,Float.MAX_VALUE));check(!full.shopState().quote(NativeShopState.registered(huge),huge,0,full::hasFlag).priceInRange(),"out-of-range price can be displayed without crashing");rejects(()->full.buy(NativeShopState.registered(huge),huge,0,fm),"huge price cannot saturate into affordable purchase");
        var changed=new ShopInventory(3,"Changed");changed.addEntry(new ShopEntry(101,1,1));rejects(()->c.shopState().quote(key,changed,0,c::hasFlag),"changed purchased row rejects stale signature");
        var clone=NativeCampaignV5.restore(c.snapshot());same(c.shopState().snapshot(),clone.shopState().snapshot(),"stock detached snapshot roundtrip");clone.buy(key,s,1,clone.party().get(1));same(2,c.shopState().quote(key,s,1,c::hasFlag).remaining(),"restored owner does not share mutable stock");
        var record=c.shopState().snapshot().get(0);rejects(()->NativeShopState.restore(List.of(record,record)),"duplicate saved stock record rejected");rejects(()->NativeShopState.restore(List.of(new NativeShopState.Purchase("shop:03",0,1,record.signature()))),"catalog alias rejected");rejects(()->NativeShopState.restore(List.of(new NativeShopState.Purchase(key,0,0,record.signature()))),"zero purchase record rejected");
        var enemy=EncounterFactory.buildMonster("Shop foe",12,1,20);var fight=c.startBattle(List.of(enemy),ignored->10);rejects(()->c.buy(key,s,1,m),"no purchase during combat");enemy.setHp(0);fight.acknowledge();
    }
    private static void key(DiagnosticApplication app,int code){var canvas=new Canvas();app.manager().getActiveScreen().onKeyPressed(new KeyEvent(canvas,KeyEvent.KEY_PRESSED,0,0,code,KeyEvent.CHAR_UNDEFINED));app.manager().update(.2f);app.manager().update(.2f);app.manager().getActiveScreen().onKeyReleased(new KeyEvent(canvas,KeyEvent.KEY_RELEASED,0,0,code,KeyEvent.CHAR_UNDEFINED));}
    private static void render(DiagnosticApplication app,String name)throws Exception{var image=new BufferedImage(GameCanvas.DESIGN_WIDTH,GameCanvas.DESIGN_HEIGHT,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{app.manager().render(g,image.getWidth(),image.getHeight());}finally{g.dispose();}check(image.getRGB(300,300)!=0xff000000,"render "+name);javax.imageio.ImageIO.write(image,"png",Path.of(System.getProperty("java.io.tmpdir"),"native-economy-"+name+".png").toFile());}
    private static void screen(Path root)throws Exception{
        var content=DiagnosticContent.exportAndLoad(DiagnosticContent.create(),root.resolve("content"));var app=new DiagnosticApplication(content,()->{});app.enterNative(DiagnosticContent.SETTLEMENT);var c=app.nativeCampaign();var shop=content.shops().get(DiagnosticContent.SHOP);String catalog=NativeShopState.registered(shop);walk(app.nativeTraversal(),5,6);key(app,KeyEvent.VK_RIGHT);key(app,KeyEvent.VK_DOWN);key(app,KeyEvent.VK_DOWN);key(app,KeyEvent.VK_ENTER);key(app,KeyEvent.VK_ENTER);same(0,c.shopState().quote(catalog,shop,2,c::hasFlag).remaining(),"actual merchant finite listing exhausted");long gold=c.gold();key(app,KeyEvent.VK_ENTER);same(gold,c.gold(),"UI sold-out confirmation no debit");key(app,KeyEvent.VK_DOWN);key(app,KeyEvent.VK_ENTER);check(!c.shopState().quote(catalog,shop,3,c::hasFlag).visible(),"actual merchant removes one-time listing");render(app,"stock");key(app,KeyEvent.VK_ESCAPE);key(app,KeyEvent.VK_RIGHT);render(app,"reopen");same(0,c.shopState().quote(catalog,shop,2,c::hasFlag).remaining(),"reopening does not restock");key(app,KeyEvent.VK_ESCAPE);
        c.party().get(0).runtime().awardExperience(100);walk(app.nativeTraversal(),19,8);key(app,KeyEvent.VK_DOWN);same(GameState.NATIVE_DIAGNOSTIC,app.manager().getActiveState(),"authored guild counter opens native training");key(app,KeyEvent.VK_G);same(2,c.party().get(0).level(),"authored counter trains");same(gold-6-7,c.gold(),"counter charges base-five plus level-one times two");key(app,KeyEvent.VK_G);same(2,c.party().get(0).level(),"actual counter cap enforced");key(app,KeyEvent.VK_1);render(app,"guild");key(app,KeyEvent.VK_ESCAPE);same(new WorldPosition(19,9),app.nativeTraversal().position(),"guild retains tile");
        var save=root.resolve("economy.pns");app.saveNative(save);same(3,java.nio.ByteBuffer.wrap(Files.readAllBytes(save)).getInt(4),"checkpoint writer version three");var fresh=new DiagnosticApplication(DiagnosticContent.load(root.resolve("content")),()->{});fresh.loadNative(save);same(c.shopState().snapshot(),fresh.nativeCampaign().shopState().snapshot(),"checkpoint preserves depleted and one-time listings");same(2,fresh.nativeCampaign().party().get(0).level(),"counter-trained level persists");
        var child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin/java").toString(),"--enable-preview","-Djava.awt.headless=true","-cp",System.getProperty("java.class.path"),NativeEconomySmokeTest.class.getName(),"--child",root.resolve("content").toString(),save.toString()).redirectErrorStream(true).start();check(child.waitFor(30,java.util.concurrent.TimeUnit.SECONDS),"economy restart child completes");var output=new String(child.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);check(child.exitValue()==0&&output.contains("NATIVE_ECONOMY_CHILD PASS"),"fresh process restores shop/guild progress: "+output);
        var decoded=NativeSaveManager.decode(Files.readAllBytes(save));var s=decoded.campaign();var first=s.shopPurchases().get(0);var invalid=new NativeShopState.Purchase(first.catalog(),first.row(),65534,first.signature());var broken=new NativeCampaignV5.Snapshot(s.members(),s.gold(),s.bankGold(),s.pendingGold(),s.readySlots(),s.curriculum(),s.questFlags(),s.worldPosition(),s.pendingChests(),List.of(invalid));var bad=new NativeSaveManager.Checkpoint(decoded.contentId(),broken,decoded.visit(),decoded.encounters());Path badFile=root.resolve("bad.pns");Files.write(badFile,NativeSaveManager.encode(bad));var before=fresh.nativeCampaign();try{fresh.loadNative(badFile);throw new AssertionError("invalid saved stock count accepted");}catch(java.io.IOException expected){check(true,"saved count validated against authored listing");}same(before,fresh.nativeCampaign(),"bad stock load preserves running owner");
        oneShotGuild();
        var inline=DiagnosticContent.create();var town=inline.maps().get(DiagnosticContent.SETTLEMENT);var inlineShop=shop(0);town.addFeature(new PlacedFeature(19,7,PlacedFeatureType.SHOP_COUNTER,inlineShop));var inlineApp=new DiagnosticApplication(inline,()->{});inlineApp.enterNative(DiagnosticContent.SETTLEMENT);walk(inlineApp.nativeTraversal(),19,6);key(inlineApp,KeyEvent.VK_DOWN);key(inlineApp,KeyEvent.VK_ENTER);var inlineKey=NativeShopState.inline(DiagnosticContent.SETTLEMENT,19,7);same(1,inlineApp.nativeCampaign().shopState().quote(inlineKey,inlineShop,0,inlineApp.nativeCampaign()::hasFlag).remaining(),"inline counter uses location identity");key(inlineApp,KeyEvent.VK_ESCAPE);var inlineSave=root.resolve("inline.pns");inlineApp.saveNative(inlineSave);inlineApp.loadNative(inlineSave);same(1,inlineApp.nativeCampaign().shopState().quote(inlineKey,inlineShop,0,inlineApp.nativeCampaign()::hasFlag).remaining(),"inline stock survives checkpoint");
    }
    private static void oneShotGuild()throws Exception{
        var content=DiagnosticContent.create();var town=content.maps().get(DiagnosticContent.SETTLEMENT);town.removeFeature(town.getFeatureAt(19,9));var flag=QuestFlag.MISC_FLAG_60;town.addFeature(new PlacedFeature(19,9,PlacedFeatureType.GUILD_COUNTER,new GuildData(5,2,0),null,flag,null));var app=new DiagnosticApplication(content,()->{});app.enterNative(DiagnosticContent.SETTLEMENT);var c=app.nativeCampaign();c.party().get(0).runtime().awardExperience(100);walk(app.nativeTraversal(),19,8);key(app,KeyEvent.VK_DOWN);key(app,KeyEvent.VK_ESCAPE);check(!c.hasFlag(flag),"leaving guild without training does not consume counter");key(app,KeyEvent.VK_UP);key(app,KeyEvent.VK_DOWN);key(app,KeyEvent.VK_G);check(c.hasFlag(flag),"successful training consumes authored counter");same(2,c.party().get(0).level(),"one-shot guild trains one level");key(app,KeyEvent.VK_G);same(2,c.party().get(0).level(),"resolved guild cannot train again before closing");same(33L,c.gold(),"resolved guild cannot charge again");key(app,KeyEvent.VK_ESCAPE);key(app,KeyEvent.VK_UP);key(app,KeyEvent.VK_DOWN);same(GameState.NATIVE_LOCAL_MAP,app.manager().getActiveState(),"consumed guild counter no longer opens");
    }
    private static void walk(LocalMapTraversal t,int tx,int ty){var map=t.map();var goal=new WorldPosition(tx,ty);var queue=new ArrayDeque<WorldPosition>();var paths=new HashMap<WorldPosition,List<Direction>>();queue.add(t.position());paths.put(t.position(),List.of());while(!queue.isEmpty()&&!paths.containsKey(goal)){var p=queue.remove();for(Direction d:Direction.values()){int dx=d==Direction.EAST?1:d==Direction.WEST?-1:0,dy=d==Direction.SOUTH?1:d==Direction.NORTH?-1:0;var n=new WorldPosition(p.x()+dx,p.y()+dy);if(!map.inBounds(n.x(),n.y())||paths.containsKey(n)||t.visibleNpcAt(n.x(),n.y())!=null)continue;var tile=AuthoredContentValidator.tileSet(map.getTileSetId()).getEntry(map.getTile(n.x(),n.y()));if(!tile.passable()||!n.equals(goal)&&map.getFeatureAt(n.x(),n.y())!=null)continue;var path=new ArrayList<>(paths.get(p));path.add(d);paths.put(n,path);queue.add(n);}}if(!paths.containsKey(goal))throw new AssertionError("No fixture route to "+goal);for(var d:paths.get(goal))t.move(d);}
}
